package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.lang.reflect.*;
/** Opt-in real native provider calls, only with ephemeral profile on isolated emulator. */
public final class LayoutLiveTest extends DocumentEditorTest {
 String profilePath;JSONArray outcomes=new JSONArray();
 @Override public void onCreate(Bundle args){profilePath=args==null?null:args.getString("liveProfilePath");start();}
 String source()throws Exception{try(InputStream in=getContext().getAssets().open("layout-decision.txt");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8").trim();}}
 void export()throws Exception{File dir=new File(getTargetContext().getFilesDir(),"qa");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"layout-live-fixed.json"))){out.write(outcomes.toString(2).getBytes("UTF-8"));}}
 @Override public void onStart(){Bundle out=new Bundle();JSONObject previous=null;try{
  if(profilePath==null||!profilePath.startsWith("/data/local/tmp/"))throw new Exception("Explicit ephemeral live profile is required");h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");Method settings=h.activity.getClass().getDeclaredMethod("privateSettings");settings.setAccessible(true);previous=new JSONObject(((JSONObject)settings.invoke(h.activity)).toString());model();h.js("LifeNative=__orig;AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  JSONObject profile=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(profilePath).toPath()),"UTF-8"));h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",profile)));profile=null;
  h.js("window.__liveNative=LifeNative;window.__liveReply=nativeReply;window.__liveIds=new Set();window.__liveReplies=[];LifeNative={call:(a,p,id)=>{const req=JSON.parse(p);if(a==='ask'&&req.tool?.name==='plan_record_layout')__liveIds.add(id);__liveNative.call(a,p,id);}};window.nativeReply=r=>{if(__liveIds.has(r.id))__liveReplies.push(r);__liveReply(r);};");
  String original=source();for(int sample=1;sample<=3;sample++){
   String body=sample==3?original.replace("万事均可量化","**万事均可量化**"):original;open("learning");input("数据化决策",body);h.js("__liveReplies=[];window.__liveStart=Date.now();document.querySelector('#doc-more').click()");h.tap("#doc-format",false);boolean finished=false;for(int i=0;i<3200;i++){if(i>3&&h.js("!document.querySelector('#doc-format').disabled").equals("true")){finished=true;break;}Thread.sleep(100);}check(finished,"Real native request leaves busy state, sample "+sample);
   JSONObject result=new JSONObject(h.js("({sample:"+sample+",elapsed:Date.now()-__liveStart,replies:__liveReplies,preview:!!document.querySelector('#doc-preview'),status:document.querySelector('#doc-status').textContent,reader:document.querySelector('#doc-flow').innerText,listItems:document.querySelectorAll('#doc-flow ol>li').length})"));outcomes.put(result);export();check(result.getBoolean("preview"),"Real provider produces applicable preview, sample "+sample);check(result.getInt("listItems")==5,"Real provider plan yields exactly five complete steps, sample "+sample);
   JSONArray replies=result.getJSONArray("replies");check(replies.length()>=1&&replies.length()<=2,"At most two real requests per short note, sample "+sample);for(int n=0;n<replies.length();n++){JSONObject data=replies.getJSONObject(n).optJSONObject("data"),usage=data==null?null:data.optJSONObject("usage"),details=usage==null?null:usage.optJSONObject("completion_tokens_details");if(details!=null)check(details.optInt("reasoning_tokens",0)==0,"Bailian effort off produces no reasoning tokens");}
   check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(body)),"Real-model preview never modifies original");if(sample==3)check(h.js("document.querySelector('#doc-flow strong').textContent==='万事均可量化'").equals("true"),"Existing emphasis survives real-model formatting");h.screenshot("layout-live-fixed-"+sample+"-preview.png");click("#doc-apply");check(!h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(body)),"Real-model layout can be adopted");h.screenshot("layout-live-fixed-"+sample+"-adopted.png");click("#doc-undo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(body)),"Real-model adoption can be undone exactly");close();
  }out.putString("stream","PASS LayoutLiveTest: "+passed+" checks; three real native provider cases\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){try{if(h!=null){h.screenshot("layout-live-fixed-failure.png");export();}}catch(Exception ignored){}out.putString("stream","FAIL LayoutLiveTest after "+passed+": "+e.getClass().getSimpleName()+" "+String.valueOf(e.getMessage()).replaceAll("sk-[A-Za-z0-9_.-]+","[hidden]")+"\n");finish(Activity.RESULT_CANCELED,out);}
 finally{if(previous!=null&&h!=null)try{Method encrypt=h.activity.getClass().getDeclaredMethod("encryptSettings",JSONObject.class);encrypt.setAccessible(true);encrypt.invoke(h.activity,previous);}catch(Exception ignored){}}}
}
